#!/bin/sh
# ==========================================================================
# FTTR 前后端一键升级脚本  --  OpenWrt 自包含离线版（大陆网络友好）
# Build: 2026-11-25T12:50:26.399Z
#
# 前端三个 bundle 已 base64 内嵌：整个升级过程不需要访问 GitHub 或任何外网。
# 你只需把这一个文件 scp 到设备即可完成检测/安装/更新/卸载。
#
# 用法:
#   sh fttr-oneclick.sh check                  # 只检测系统与当前状态（不改任何文件）
#   sh fttr-oneclick.sh status                 # 查看已安装 bundle 的版本/md5
#   sh fttr-oneclick.sh install  [fttrd.apk]   # 安装前端（自动备份），可选同时装后端 apk
#   sh fttr-oneclick.sh update   [fttrd.apk]   # 同 install
#   sh fttr-oneclick.sh uninstall              # 卸载：从最近备份恢复前端文件
#   sh fttr-oneclick.sh all      [fttrd.apk]   # 一键：检测 -> 备份 -> 安装 -> 校验 -> 状态
#   sh fttr-oneclick.sh help
#
# 大陆环境说明:
#   * 默认完全离线，脚本内嵌所有前端文件，不 curl/wget 任何 GitHub 地址。
#   * 后端 apk 也通过本地参数传入（先 scp 到设备），同样不访问外网。
#   * 需要更新到新版本时，在能上网的 PC 上拿到新脚本后重新 scp 覆盖即可。
# ==========================================================================

set -u
APP=fttr-oneclick
VER=3.0
BK_ROOT=/etc/fttr-oneclick
DEFAULT_LUCI=/www/luci-static/resources/view/fttr
LUCI_DIR=
PKG_MGR=
LAST_BACKUP=

MD5_CONFIG=6d4a369a8fedeb3b173b90ad0baf52a6
MD5_INDEX=5398934a693818748da09e2e812a8aa7
MD5_TOPOLOGY=9cca77fb93ec013c9eaa4fd38636235b

info() { echo "[INFO] $*"; }
ok()   { echo "[ OK ] $*"; }
warn() { echo "[WARN] $*"; }
fail() { echo "[FAIL] $*" >&2; }
line() { echo "============================================================"; }

need_cmd() { command -v "$1" >/dev/null 2>&1; }

detect_luci_dir() {
    for d in /www/luci-static/resources/view/fttr \
             /usr/share/luci/htdocs/luci-static/resources/view/fttr \
             /rom/www/luci-static/resources/view/fttr; do
        [ -d "$d" ] && { LUCI_DIR="$d"; return 0; }
    done
    if need_cmd find; then
        f=$(find /www /usr/share/luci -path '*view/fttr/config.js' 2>/dev/null | head -1)
        [ -n "$f" ] && { LUCI_DIR=$(dirname "$f"); return 0; }
    fi
    LUCI_DIR=$DEFAULT_LUCI
    return 1
}

md5of() {
    if need_cmd md5sum; then md5sum "$1" 2>/dev/null | awk '{print $1}'
    elif need_cmd busybox; then busybox md5sum "$1" 2>/dev/null | awk '{print $1}'
    else echo NOMD5; fi
}

detect_system() {
    line
    echo " FTTR 一键升级 · 系统检测"
    line
    if [ -f /etc/openwrt_release ]; then
        . /etc/openwrt_release
        info "系统    : ${DISTRIB_ID:-OpenWrt} ${DISTRIB_RELEASE:-?} [${DISTRIB_TARGET:-?}]"
        info "架构    : ${DISTRIB_ARCH:-?} / $(uname -m 2>/dev/null)"
    else
        warn "未找到 /etc/openwrt_release，可能不是标准 OpenWrt"
    fi
    if need_cmd apk; then PKG_MGR=apk; info "包管理  : apk"
    elif need_cmd opkg; then PKG_MGR=opkg; info "包管理  : opkg"
    else warn "包管理  : 未检测到 apk/opkg（前端安装不受影响）"; fi

    if detect_luci_dir; then info "FTTR UI : $LUCI_DIR"
    else warn "FTTR UI : 未找到目录，将使用默认 $DEFAULT_LUCI"; fi

    if need_cmd uci; then
        lp=$(uci -q get fttr.h3c.lan_ports 2>/dev/null)
        [ -n "$lp" ] && info "lan_ports: $lp（前端按此数量收敛显示）" \
                     || info "lan_ports: 未显式设置（按默认 16）"
    fi
    if need_cmd ubus; then
        ul=$(ubus list 2>/dev/null | grep '^fttr' | tr '\n' ' ')
        [ -n "$ul" ] && info "fttrd   : 已注册 [$ul]" \
                     || warn "fttrd   : ubus 未检测到，可能未运行"
    fi
    LAST_BACKUP=$(cat "$BK_ROOT/last_backup" 2>/dev/null)
    [ -n "$LAST_BACKUP" ] && info "备份    : $BK_ROOT/backup/$LAST_BACKUP" \
                          || info "备份    : 尚无"
    line
}

show_status() {
    detect_luci_dir
    line
    echo " 当前 bundle 状态"
    line
    for f in config.js index.js topology.js; do
        case $f in
            config.js)   exp=$MD5_CONFIG ;;
            index.js)    exp=$MD5_INDEX ;;
            topology.js) exp=$MD5_TOPOLOGY ;;
        esac
        path=$LUCI_DIR/$f
        if [ -f "$path" ]; then
            got=$(md5of "$path")
            if [ "$got" = "$exp" ]; then ok "$f : 已是本版本 ($got)"
            else warn "$f : 已安装但版本不同 (当前 $got / 本包 $exp)"; fi
        else
            warn "$f : 未安装 ($path 不存在)"
        fi
    done
    line
}

do_backup() {
    detect_luci_dir
    ts=$(date +%Y%m%d-%H%M%S 2>/dev/null)
    [ -z "$ts" ] && ts=unknown
    bk="$BK_ROOT/backup/$ts"
    mkdir -p "$bk" || { fail "无法创建备份目录 $bk"; return 1; }
    : > "$bk/FILES"
    for f in config.js index.js topology.js; do
        if [ -f "$LUCI_DIR/$f" ]; then
            cp -p "$LUCI_DIR/$f" "$bk/$f" && echo "$f" >> "$bk/FILES" \
                || { fail "备份 $f 失败"; return 1; }
        fi
    done
    echo "$ts" > "$BK_ROOT/last_backup"
    info "原文件已备份到 $bk"
}

write_bundle() {
    name=$1; exp=$2; tag=$3
    tmp="$LUCI_DIR/$name.oneclick.$$"
    case $tag in
        config)
            base64 -d > "$tmp" <<'FTTR_B64_CONFIG_EOF'

FTTR_B64_CONFIG_EOF
            ;;
        index)
            base64 -d > "$tmp" <<'FTTR_B64_INDEX_EOF'

FTTR_B64_INDEX_EOF
            ;;
        topology)
            base64 -d > "$tmp" <<'FTTR_B64_TOPOLOGY_EOF'

FTTR_B64_TOPOLOGY_EOF
            ;;
    esac
    if [ ! -s "$tmp" ]; then fail "$name 解码失败（空文件）"; rm -f "$tmp"; return 1; fi
    got=$(md5of "$tmp")
    if [ "$got" != "$exp" ]; then fail "$name md5 不匹配 ($got != $exp)"; rm -f "$tmp"; return 1; fi
    if [ ! -d "$LUCI_DIR" ]; then mkdir -p "$LUCI_DIR" || { fail "无法创建 $LUCI_DIR"; rm -f "$tmp"; return 1; }; fi
    mv -f "$tmp" "$LUCI_DIR/$name" || { fail "$name 写入失败"; rm -f "$tmp"; return 1; }
    ok "$name 已安装 [$(wc -c < "$LUCI_DIR/$name") bytes, md5 $got]"
}

clear_cache() {
    rm -rf /tmp/luci-modulecache /tmp/luci-indexcache /tmp/luci-indexcache.* 2>/dev/null
    info "LuCI 缓存已清理（浏览器仍需 Ctrl+F5 强制刷新）"
}

do_apk() {
    apkfile=${1:-}
    [ -z "$apkfile" ] && return 0
    [ ! -f "$apkfile" ] && { fail "后端 apk 不存在: $apkfile"; return 1; }
    case $PKG_MGR in
        apk)  apk add --allow-untrusted "$apkfile" || { fail "apk 安装失败"; return 1; } ;;
        opkg) opkg install --force-depends "$apkfile" || { fail "opkg 安装失败"; return 1; } ;;
        *) fail "未检测到包管理器，无法安装后端 apk"; return 1 ;;
    esac
    if [ -x /etc/init.d/fttr ]; then /etc/init.d/fttr restart >/dev/null 2>&1; fi
    ok "后端 apk 已安装并重启 fttrd"
    if need_cmd ubus; then ubus call fttr config_check 2>/dev/null; fi
}

do_install() {
    detect_system
    do_backup || return 1
    write_bundle config.js   "$MD5_CONFIG"   config    || { warn "安装失败，正在回滚"; do_uninstall; return 1; }
    write_bundle index.js    "$MD5_INDEX"    index     || { warn "安装失败，正在回滚"; do_uninstall; return 1; }
    write_bundle topology.js "$MD5_TOPOLOGY" topology || { warn "安装失败，正在回滚"; do_uninstall; return 1; }
    do_apk "${1:-}"
    clear_cache
    line
    echo " 安装完成"
    line
    info "验证：浏览器 Ctrl+F5；FTTR→概览下联端口只显示 lan_ports 个；FTTR→拓扑无陈旧提示。"
    if [ -n "$LAST_BACKUP" ]; then info "回退命令：sh $0 uninstall"; fi
    return 0
}

do_uninstall() {
    detect_luci_dir
    ts=$(cat "$BK_ROOT/last_backup" 2>/dev/null)
    if [ -z "$ts" ] || [ ! -d "$BK_ROOT/backup/$ts" ]; then
        fail "找不到备份，拒绝卸载以免误删文件"; return 1
    fi
    bk="$BK_ROOT/backup/$ts"
    info "从 $bk 恢复"
    for f in config.js index.js topology.js; do
        if [ -f "$bk/$f" ]; then
            cp -p "$bk/$f" "$LUCI_DIR/$f" && ok "$f 已恢复" || fail "$f 恢复失败"
        else
            rm -f "$LUCI_DIR/$f" && ok "$f 已移除（原本不存在）" || fail "$f 移除失败"
        fi
    done
    clear_cache
    info "前端已恢复原版本。若装过后端 apk，请用 apk del openwrt-fttr 单独卸载。"
}

usage() {
    cat <<'FTTR_USAGE_EOF'
FTTR 前后端一键升级脚本（自包含离线版）

  check                  检测 OpenWrt 系统/包管理器/LuCI 路径/fttrd/当前状态（只读）
  status                 查看三个 bundle 的安装版本与 md5
  install  [fttrd.apk]   安装前端（自动备份），可选同时安装后端 apk
  update   [fttrd.apk]   同 install
  uninstall              从最近备份恢复前端文件
  all      [fttrd.apk]   一键完成：检测 → 备份 → 安装 → 校验 → 状态
  help                   显示本帮助

示例:
  sh fttr-oneclick.sh check
  sh fttr-oneclick.sh all
  sh fttr-oneclick.sh all /tmp/openwrt-fttr-2026.apk
  sh fttr-oneclick.sh uninstall
FTTR_USAGE_EOF
}

case ${1:-help} in
    check)     detect_system; show_status ;;
    status)    show_status ;;
    install|update|all) do_install "${2:-}" ;;
    uninstall) do_uninstall ;;
    help|-h|--help|*) usage ;;
esac
